## 06_prepare_pathway_objects_brca.R
##
## Purpose:
##   Build compact BRCA pathway-analysis objects for OmicsKit vignettes from:
##
##   1) standardized GSEAPreranked imports generated by:
##        data-raw/brca/05_import_gsea_pipeline_outputs_brca.R
##
##   2) MSigDB GMT files stored in:
##        inst/extdata/brca/gsea_outputs/gmt/
##
##   3) ranked gene lists stored in:
##        inst/extdata/brca/gsea_outputs/rnk/
##
## This version fixes pathway-to-GMT matching by preserving and normalizing
## pathway names from GMT files. It is aligned with the vignette workflow:
##
##   list_gmts() / GMT gene sets
##   getgenesPA()
##   addgenesPA()
##   pathway clustering

options(stringsAsFactors = FALSE)

project_file <- function(...) {
  if (requireNamespace("here", quietly = TRUE)) {
    here::here(...)
  } else {
    file.path(...)
  }
}

require_package <- function(package, why = NULL) {
  if (!requireNamespace(package, quietly = TRUE)) {
    stop(
      "Package '", package, "' is required",
      if (!is.null(why)) paste0(" ", why),
      ".",
      call. = FALSE
    )
  }
  invisible(TRUE)
}

require_file <- function(path, label) {
  if (!file.exists(path)) {
    stop(
      "Required file is missing: ", label, "\n",
      "Expected location: ", normalizePath(path, mustWork = FALSE),
      call. = FALSE
    )
  }
  invisible(path)
}

require_dir <- function(path, label) {
  if (!dir.exists(path)) {
    stop(
      "Required directory is missing: ", label, "\n",
      "Expected location: ", normalizePath(path, mustWork = FALSE),
      call. = FALSE
    )
  }
  invisible(path)
}

require_package("data.table")
require_package("usethis", "to save pathway example objects")

library(data.table)

## -------------------------------------------------------------------------
## Name normalization
## -------------------------------------------------------------------------

normalize_pathway_name <- function(x) {
  x <- as.character(x)
  x <- trimws(x)
  x <- gsub("[[:space:]]+", "_", x)
  x <- gsub("-", "_", x)
  toupper(x)
}

