## -------------------------------------------------------------------------
## Read GMT files
## -------------------------------------------------------------------------

read_gmt_file <- function(path) {
  lines <- readLines(path, warn = FALSE)
  lines <- lines[nzchar(trimws(lines))]

  parsed <- strsplit(lines, "\t", fixed = TRUE)

  pathway_names <- vapply(parsed, `[[`, character(1), 1)
  pathway_keys <- normalize_pathway_name(pathway_names)

  gene_sets <- lapply(parsed, function(parts) {
    genes <- parts[-c(1, 2)]
    genes <- toupper(trimws(genes))
    genes <- genes[nzchar(genes)]
    unique(genes)
  })

  names(gene_sets) <- pathway_keys

  ## If duplicated after normalization, keep the first.
  gene_sets <- gene_sets[!duplicated(names(gene_sets))]
  gene_sets[lengths(gene_sets) > 0]
}

infer_collection_from_gmt <- function(path) {
  file <- basename(path)

  if (grepl("^h\\.all\\.", file, ignore.case = TRUE)) {
    return("Hallmark")
  }

  if (grepl("^c5\\.go\\.bp\\.", file, ignore.case = TRUE)) {
    return("GO_BP")
  }

  tools::file_path_sans_ext(file)
}

gmt_files <- list.files(
  gmt_dir,
  pattern = "\\.gmt$",
  full.names = TRUE
)

if (length(gmt_files) == 0) {
  stop(
    "No GMT files were found in: ",
    normalizePath(gmt_dir, mustWork = FALSE),
    call. = FALSE
  )
}

brca_geneset_list_by_collection <- list()

for (gmt_file in gmt_files) {
  collection <- infer_collection_from_gmt(gmt_file)
  brca_geneset_list_by_collection[[collection]] <- read_gmt_file(gmt_file)
}

## Preserve pathway names from each GMT list.
## Do NOT use unlist(..., use.names = FALSE), because that removes gene-set names
## and makes pathway matching impossible.
brca_geneset_list <- list()

for (collection in names(brca_geneset_list_by_collection)) {
  current <- brca_geneset_list_by_collection[[collection]]
  for (nm in names(current)) {
    if (is.null(brca_geneset_list[[nm]])) {
      brca_geneset_list[[nm]] <- current[[nm]]
    }
  }
}

if (length(brca_geneset_list) < 3) {
  stop(
    "At least three gene sets are required after reading GMT files. Observed: ",
    length(brca_geneset_list),
    call. = FALSE
  )
}

message("Loaded GMT gene sets: ", length(brca_geneset_list))
message("Example GMT names: ", paste(head(names(brca_geneset_list), 5), collapse = ", "))

## -------------------------------------------------------------------------
## Read RNK files
## -------------------------------------------------------------------------

read_rnk <- function(path) {
  require_file(path, basename(path))

  x <- data.table::fread(
    path,
    header = FALSE,
    col.names = c("gene", "score")
  )

  x[, gene := toupper(trimws(as.character(gene)))]
  x[, score := suppressWarnings(as.numeric(score))]
  x <- x[!is.na(gene) & gene != "" & is.finite(score)]

  if (nrow(x) == 0) {
    stop("RNK file has no valid rows: ", path, call. = FALSE)
  }

  setorder(x, -score, gene)

  scores <- x$score
  names(scores) <- x$gene

  scores
}

