required_columns <- c(
  "pathway",
  "collection",
  "comparison",
  "ES",
  "NES",
  "pvalue",
  "padj",
  "FWER",
  "size",
  "direction"
)

optional_columns <- c(
  "method",
  "source",
  "rank_metric",
  "report_side",
  "rank_at_max",
  "leading_edge",
  "core_enrichment",
  "output_label",
  "source_file",
  "significant_fdr_0_25",
  "significant_fdr_0_05"
)

validate_standardized_gsea <- function(x, object_name) {
  missing_cols <- setdiff(required_columns, names(x))

  if (length(missing_cols) > 0) {
    stop(
      "Missing required standardized columns in ",
      object_name,
      ":\n- ",
      paste(missing_cols, collapse = "\n- "),
      call. = FALSE
    )
  }

  invisible(TRUE)
}

