## -------------------------------------------------------------------------
## Convert standardized schema to OmicsKit PA-compatible schema
## -------------------------------------------------------------------------

extract_leading_edge_metric <- function(x, key) {
  x <- as.character(x)

  out <- rep(NA_real_, length(x))
  ok <- !is.na(x) & nzchar(trimws(x))

  if (!any(ok)) {
    return(out)
  }

  pattern <- paste0("(?i)", key, "\\s*=\\s*([0-9.]+)\\s*%?")
  m <- regexec(pattern, x[ok], perl = TRUE)
  hits <- regmatches(x[ok], m)

  vals <- vapply(
    hits,
    function(z) {
      if (length(z) >= 2) {
        suppressWarnings(as.numeric(z[2]))
      } else {
        NA_real_
      }
    },
    numeric(1)
  )

  out[ok] <- vals
  out
}

make_pa_table <- function(x) {
  keep <- intersect(c(required_columns, optional_columns), names(x))
  x <- copy(x[, ..keep])

  if (!"leading_edge" %in% names(x)) {
    x[, leading_edge := NA_character_]
  }

  if (!"rank_at_max" %in% names(x)) {
    x[, rank_at_max := NA_real_]
  }

  ## Compatibility columns expected by OmicsKit pathway helpers.
  x[, NAME := pathway]
  x[, NAME_KEY := normalize_pathway_name(pathway)]
  x[, COLLECTION := collection]
  x[, COMPARISON := comparison]
  x[, SIZE := as.integer(size)]
  x[, `NOM p-val` := as.numeric(pvalue)]
  x[, FDR := as.numeric(padj)]
  x[, `FDR q-val` := as.numeric(padj)]
  x[, `FWER p-val` := as.numeric(FWER)]
  x[, `RANK AT MAX` := suppressWarnings(as.numeric(rank_at_max))]
  x[, `LEADING EDGE` := as.character(leading_edge)]
  x[, Log10FDR := -log10(pmax(FDR, .Machine$double.xmin))]

  ## Parse GSEA leading-edge summary string:
  ## "tags=34%, list=12%, signal=30%"
  x[, tags := extract_leading_edge_metric(`LEADING EDGE`, "tags")]
  x[, `list` := extract_leading_edge_metric(`LEADING EDGE`, "list")]
  x[, signal := extract_leading_edge_metric(`LEADING EDGE`, "signal")]

  ## Add a stable identifier used for clustering/network examples.
  x[, PA_ID := paste(COMPARISON, COLLECTION, NAME_KEY, sep = "::")]

  x[, abs_NES := abs(NES)]
  setorder(x, COMPARISON, COLLECTION, FDR, -abs_NES, NAME)
  x[, abs_NES := NULL]

  x[]
}

