## -------------------------------------------------------------------------
## Build clustering gene sets from GMT memberships
## -------------------------------------------------------------------------

source(project_file("R", "doclust_PA.R"))

make_clustering_geneset_list <- function(pa_data, geneset_list) {
  keys <- pa_data$PA_ID

  out <- vector("list", length(keys))
  names(out) <- keys

  for (i in seq_along(keys)) {
    pathway_key <- pa_data$NAME_KEY[[i]]

    genes <- geneset_list[[pathway_key]]

    if (is.null(genes)) {
      genes <- character()
    }

    out[[i]] <- unique(genes)
  }

  out <- out[lengths(out) > 0]
  out
}

cluster_threshold <- 0.05

clustering_input <- brca_pa_merged[
  !is.na(FDR) & FDR < cluster_threshold
]

if (nrow(clustering_input) < 3) {
  message(
    "Fewer than three pathways with FDR < 0.05. ",
    "Using FDR < 0.25 for the example clustering object."
  )

  cluster_threshold <- 0.25

  clustering_input <- brca_pa_merged[
    !is.na(FDR) & FDR < cluster_threshold
  ]
}

if (nrow(clustering_input) < 3) {
  stop(
    "At least three significant pathways are required for clustering. ",
    "Observed with FDR < ", cluster_threshold, ": ",
    nrow(clustering_input),
    call. = FALSE
  )
}

brca_clustering_geneset_list <- make_clustering_geneset_list(
  pa_data = clustering_input,
  geneset_list = brca_geneset_list
)

if (length(brca_clustering_geneset_list) < 3) {
  unmatched <- setdiff(unique(clustering_input$NAME_KEY), names(brca_geneset_list))

  stop(
    "At least three clustering gene sets with GMT memberships are required. ",
    "Observed: ", length(brca_clustering_geneset_list), "\n",
    "This usually means pathway names in the PA table do not match GMT names.\n",
    "First unmatched PA names:\n- ",
    paste(head(unmatched, 20), collapse = "\n- "),
    "\nFirst GMT names:\n- ",
    paste(head(names(brca_geneset_list), 20), collapse = "\n- "),
    call. = FALSE
  )
}

clustering_results <- data.frame(
  GeneSet = names(brca_clustering_geneset_list),
  FDR = clustering_input$FDR[
    match(
      names(brca_clustering_geneset_list),
      clustering_input$PA_ID
    )
  ],
  stringsAsFactors = FALSE
)

brca_pa_similarity <- geneset_similarity(
  geneset_list = brca_clustering_geneset_list,
  results = clustering_results,
  fdr_th = cluster_threshold
)

brca_pa_clustering <- do_clust(brca_pa_similarity)

if ("heatmap" %in% names(brca_pa_clustering)) {
  brca_pa_clustering$heatmap <- NULL
}

